from typing import List


def string_xor(a: str, b: str) -> str:
    """Return the bitwise XOR of two binary strings."""
    if a == "" or b == "":
        return ""
    if a[0] == b[0]:
        return "0" + string_xor(a[1:], b[1:])
    return "1" + string_xor(a[1:], b[1:])

